    require_bool(manifest, "private", true)?;
    require_text(manifest, "type", "commonjs")?;
    reject_dependency_entries(manifest, "npm package manifest")?;
    validate_manager(manifest)?;

    let lock: JsonValue = serde_json::from_slice(lock).context("npm package lock must be JSON")?;
    let lock = lock
        .as_object()
        .context("npm package lock must be an object")?;
    validate_lock_header(lock, &name, &version)?;
    reject_dependency_entries(lock, "npm package lock")?;
    let packages = lock
        .get("packages")
        .and_then(JsonValue::as_object)
        .context("npm package lock requires a packages object")?;
    if packages.len() != 1 {
        bail!("npm zero-dependency package lock must contain only its root package");
    }
    let root = packages
        .get("")
        .and_then(JsonValue::as_object)
