pub fn execute_hotpath(
    registry: &HotpathRegistry,
    hotpath_id: &str,
    inputs: &PrimordialInputs,
    ctx: &ResolutionContext,
) -> Result<Value> {
    let hotpath = registry
        .get(hotpath_id)
        .ok_or_else(|| anyhow::anyhow!("unknown hotpath `{hotpath_id}`"))?;
    execute(registry, hotpath, inputs, ctx)
